PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS content (id INTEGER PRIMARY KEY CHECK(id=1), draft TEXT NOT NULL, draft_rev INTEGER NOT NULL DEFAULT 1, published TEXT NOT NULL, published_rev TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS media (id TEXT PRIMARY KEY, name TEXT NOT NULL, mime TEXT NOT NULL, bytes INTEGER NOT NULL CHECK(bytes>0 AND bytes<=524288), width INTEGER NOT NULL CHECK(width BETWEEN 1 AND 2000), height INTEGER NOT NULL CHECK(height BETWEEN 1 AND 2000), body BLOB NOT NULL, created_at TEXT NOT NULL);
CREATE TRIGGER IF NOT EXISTS media_storage_limit BEFORE INSERT ON media WHEN (SELECT COUNT(*) FROM media)>=60 OR (SELECT COALESCE(SUM(bytes),0) FROM media)+NEW.bytes>20971520 BEGIN SELECT RAISE(ABORT,'MEDIA_LIMIT'); END;
CREATE TABLE IF NOT EXISTS quota (key TEXT PRIMARY KEY, day TEXT NOT NULL, count INTEGER NOT NULL CHECK(count>=0));
CREATE INDEX IF NOT EXISTS quota_day ON quota(day);
CREATE TABLE IF NOT EXISTS visits (day TEXT PRIMARY KEY, count INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS counters (key TEXT PRIMARY KEY, count INTEGER NOT NULL DEFAULT 0);
INSERT OR IGNORE INTO counters(key,count) VALUES('total',0);
